package com.rastudio.commerce.user;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="app_user") public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="organization_id",nullable=false) public Long organizationId; @Column(name="full_name",nullable=false) public String fullName; @Column(nullable=false) public String email; @Column(name="password_hash",nullable=false) public String passwordHash; @Enumerated(EnumType.STRING) @Column(nullable=false) public UserRole role; @Enumerated(EnumType.STRING) @Column(nullable=false) public UserStatus status=UserStatus.PENDING; @Column(name="email_verified_at") public LocalDateTime emailVerifiedAt; @Column(name="invited_by") public Long invitedBy; @Column(name="last_login_at") public LocalDateTime lastLoginAt; @Column(name="created_at",updatable=false) public LocalDateTime createdAt; @Column(name="updated_at") public LocalDateTime updatedAt; @PrePersist void created(){createdAt=LocalDateTime.now();updatedAt=createdAt;} @PreUpdate void updated(){updatedAt=LocalDateTime.now();} }